// Suggestion: Add a cleanup function
function clearGameHistory(uint256 gameId) external {
    Game storage game = games[gameId];
    require(msg.sender == game.player1 || msg.sender == game.player2, "Unauthorized");
    require(game.status == uint8(GameStatus.COMPLETED) || game.status == uint8(GameStatus.CANCELLED), "Game not finished");
    // Optional: add a time delay before allowing deletion.
    // require(block.timestamp > game.lastAction + 30 days, "Deletion grace period not over");

    delete games[gameId];
}

